select *
from jsh_vehicle
where ifnull(delete_flag,'0') != '1'
  and enabled = 1
  and (
      license_plate_no like #{kw}
   or concat(ifnull(license_plate_province,''), ifnull(license_plate_no,'')) like #{kw}
   or customer_name    like #{kw}
   or customer_phone   like #{kw}
   or vin              like #{kw}
  )
order by id desc
limit #{limit}

select *
from jsh_vehicle
where ifnull(delete_flag,'0') != '1'


    and license_plate_no like #{bindPlate}



    and customer_name like #{bindName}



    and customer_phone like #{bindPhone}


    and enabled = #{enabled}

order by id desc

